-- NexVelt RetailOS: DEMO CATALOGUE for NR Collections (clothing + jewellery).
-- GENERATED by scripts/gen-demo-catalogue.mjs. Not part of the approved migration manifest; it only calls the app's own functions.
--
-- WHAT IT DOES
--   Creates 8 clothing styles (32 size/colour variants, 208 pieces in stock) and 22 individually tagged jewellery pieces
--   (14 imitation, 8 gold/silver) with fixed tag prices. Every barcode is a valid EAN-13 you can print and scan.
--   Total stock value at selling price: Rs 5,56,698. Prices are illustrative demo values, not derived from a metal rate.
-- HOW
--   It acts as the shop OWNER (the active tenant_owner), so permissions, barcodes, categories, stock movements and the audit log are
--   handled by the same database functions the app uses. Nothing is inserted into tables directly.
-- SAFE TO RUN TWICE
--   Deterministic idempotency keys: a second run changes nothing (the functions report the original result as "replayed").
-- WHERE
--   Run in the Supabase SQL editor, as postgres, ONCE, on the project you will demo. It writes real rows (visible in the app).
--   If you change a name, price or stock here AFTER running, use the app's Products screen instead, not this script.
-- REMOVING IT
--   Bills are immutable, so sold demo items cannot be deleted. Items nobody has sold can be switched off in Products > open item > Switch off.
-- The last statement returns a summary; the editor shows only the last result.

begin;

-- act as the owner, exactly as a signed-in owner session would
select set_config('request.jwt.claims',
  json_build_object('sub', (select m.user_id from retailos.tenant_memberships m join retailos.roles r on r.id = m.role_id
                             where r.key = 'tenant_owner' and m.status = 'ACTIVE' order by m.created_at limit 1),
                    'role', 'authenticated', 'aal', 'aal1')::text, true);
set local role authenticated;

create or replace function pg_temp.seed_clothing(p_branch uuid, p_name text, p_style text, p_cat text, p_hsn text, p_variants jsonb) returns void
language plpgsql as $f$
begin
  perform retailos.catalog_create_clothing(p_branch, p_name, p_style, p_cat, p_hsn, p_variants, md5('nrc-demo-clothing|' || p_style)::uuid);
end;
$f$;

create or replace function pg_temp.seed_jewellery(p_branch uuid, p_kind text, p_name text, p_cat text, p_tag text, p_price bigint,
                                                  p_metal text, p_purity text, p_gross numeric, p_net numeric, p_hsn text, p_barcode text) returns void
language plpgsql as $f$
begin
  perform retailos.catalog_create_jewellery(p_branch, p_kind, p_name, p_cat, p_tag, p_price, p_metal, p_purity, p_gross, p_net, p_hsn, p_barcode,
                                            md5('nrc-demo-jewellery|' || p_tag)::uuid);
end;
$f$;

do $seed$
declare
  v_branch uuid;
begin
  select b.id into v_branch from retailos.branches b where b.code = 'MAIN' order by b.created_at limit 1;
  if v_branch is null then raise exception 'No MAIN branch found: run the tenant bootstrap first.'; end if;
  if (select auth.uid()) is null then raise exception 'No active owner found: run the tenant bootstrap first.'; end if;

  -- clothing
  perform pg_temp.seed_clothing(v_branch, 'Men''s Cotton Shirt', 'MCS101', 'Shirts', '6205', '[{"size":"M","colour":"Sky Blue","pricePaise":129900,"openingStock":8,"barcode":"8901230000018"},{"size":"L","colour":"Sky Blue","pricePaise":129900,"openingStock":10,"barcode":"8901230000025"},{"size":"XL","colour":"Sky Blue","pricePaise":129900,"openingStock":6,"barcode":"8901230000032"},{"size":"M","colour":"White","pricePaise":129900,"openingStock":7,"barcode":"8901230000049"},{"size":"L","colour":"White","pricePaise":129900,"openingStock":9,"barcode":"8901230000056"},{"size":"XL","colour":"White","pricePaise":129900,"openingStock":5,"barcode":"8901230000063"}]'::jsonb);
  perform pg_temp.seed_clothing(v_branch, 'Men''s Formal Shirt', 'MFS102', 'Shirts', '6205', '[{"size":"M","colour":"Light Grey","pricePaise":159900,"openingStock":6,"barcode":"8901230000070"},{"size":"L","colour":"Light Grey","pricePaise":159900,"openingStock":8,"barcode":"8901230000087"},{"size":"XL","colour":"Light Grey","pricePaise":159900,"openingStock":4,"barcode":"8901230000094"}]'::jsonb);
  perform pg_temp.seed_clothing(v_branch, 'Slim Fit Jeans', 'JNS201', 'Jeans', '6203', '[{"size":"30","colour":"Indigo","pricePaise":189900,"openingStock":6,"barcode":"8901230000100"},{"size":"32","colour":"Indigo","pricePaise":189900,"openingStock":9,"barcode":"8901230000117"},{"size":"34","colour":"Indigo","pricePaise":189900,"openingStock":7,"barcode":"8901230000124"},{"size":"36","colour":"Indigo","pricePaise":189900,"openingStock":4,"barcode":"8901230000131"},{"size":"32","colour":"Black","pricePaise":199900,"openingStock":5,"barcode":"8901230000148"}]'::jsonb);
  perform pg_temp.seed_clothing(v_branch, 'Printed Cotton Kurti', 'KRT301', 'Kurtis', '6204', '[{"size":"S","colour":"Maroon","pricePaise":89900,"openingStock":6,"barcode":"8901230000155"},{"size":"M","colour":"Maroon","pricePaise":89900,"openingStock":10,"barcode":"8901230000162"},{"size":"L","colour":"Maroon","pricePaise":89900,"openingStock":8,"barcode":"8901230000179"},{"size":"M","colour":"Teal","pricePaise":89900,"openingStock":7,"barcode":"8901230000186"},{"size":"L","colour":"Teal","pricePaise":89900,"openingStock":6,"barcode":"8901230000193"}]'::jsonb);
  perform pg_temp.seed_clothing(v_branch, 'Anarkali Kurti Set', 'ANK302', 'Kurtis', '6204', '[{"size":"M","colour":"Mustard","pricePaise":249900,"openingStock":4,"barcode":"8901230000209"},{"size":"L","colour":"Mustard","pricePaise":249900,"openingStock":5,"barcode":"8901230000216"},{"size":"XL","colour":"Mustard","pricePaise":249900,"openingStock":3,"barcode":"8901230000223"}]'::jsonb);
  perform pg_temp.seed_clothing(v_branch, 'Silk Blend Saree', 'SAR401', 'Sarees', '5007', '[{"size":"","colour":"Royal Red","pricePaise":349900,"openingStock":5,"barcode":"8901230000230"},{"size":"","colour":"Bottle Green","pricePaise":349900,"openingStock":4,"barcode":"8901230000247"},{"size":"","colour":"Peacock Blue","pricePaise":379900,"openingStock":3,"barcode":"8901230000254"}]'::jsonb);
  perform pg_temp.seed_clothing(v_branch, 'Cotton Palazzo', 'PLZ601', 'Bottoms', '6204', '[{"size":"M","colour":"Black","pricePaise":74900,"openingStock":9,"barcode":"8901230000261"},{"size":"L","colour":"Black","pricePaise":74900,"openingStock":9,"barcode":"8901230000278"},{"size":"M","colour":"Navy","pricePaise":74900,"openingStock":6,"barcode":"8901230000285"}]'::jsonb);
  perform pg_temp.seed_clothing(v_branch, 'Kids Graphic T-Shirt', 'KID501', 'Kids Wear', '6109', '[{"size":"4Y","colour":"Yellow","pricePaise":49900,"openingStock":8,"barcode":"8901230000292"},{"size":"6Y","colour":"Yellow","pricePaise":49900,"openingStock":8,"barcode":"8901230000308"},{"size":"8Y","colour":"Yellow","pricePaise":49900,"openingStock":6,"barcode":"8901230000315"},{"size":"6Y","colour":"Red","pricePaise":49900,"openingStock":7,"barcode":"8901230000322"}]'::jsonb);

  -- jewellery
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Kundan Necklace Set', 'Necklaces', 'IJ9000001', 49900, null, null, null, null, null, '8901230000339');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Kundan Necklace Set', 'Necklaces', 'IJ9000002', 49900, null, null, null, null, null, '8901230000346');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Jhumka Earrings', 'Earrings', 'IJ9000003', 29900, null, null, null, null, null, '8901230000353');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Jhumka Earrings', 'Earrings', 'IJ9000004', 29900, null, null, null, null, null, '8901230000360');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Oxidised Bangles Set', 'Bangles', 'IJ9000005', 34900, null, null, null, null, null, '8901230000377');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Oxidised Bangles Set', 'Bangles', 'IJ9000006', 34900, null, null, null, null, null, '8901230000384');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Pearl Choker', 'Necklaces', 'IJ9000007', 79900, null, null, null, null, null, '8901230000391');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Pearl Choker', 'Necklaces', 'IJ9000008', 79900, null, null, null, null, null, '8901230000407');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Temple Haaram', 'Necklaces', 'IJ9000009', 129900, null, null, null, null, null, '8901230000414');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Temple Haaram', 'Necklaces', 'IJ9000010', 129900, null, null, null, null, null, '8901230000421');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Meenakari Maang Tikka', 'Head Jewellery', 'IJ9000011', 39900, null, null, null, null, null, '8901230000438');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Meenakari Maang Tikka', 'Head Jewellery', 'IJ9000012', 39900, null, null, null, null, null, '8901230000445');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Payal Anklet Pair', 'Anklets', 'IJ9000013', 25900, null, null, null, null, null, '8901230000452');
  perform pg_temp.seed_jewellery(v_branch, 'IMITATION', 'Payal Anklet Pair', 'Anklets', 'IJ9000014', 25900, null, null, null, null, null, '8901230000469');
  perform pg_temp.seed_jewellery(v_branch, 'PRECIOUS', 'Gold Chain 22K', 'Gold Chains', 'GJ9000001', 5850000, 'GOLD', '22K', 8.2, 8.15, '7113', '8901230000476');
  perform pg_temp.seed_jewellery(v_branch, 'PRECIOUS', 'Gold Ring 22K', 'Gold Rings', 'GJ9000002', 2800000, 'GOLD', '22K', 3.5, 3.42, '7113', '8901230000483');
  perform pg_temp.seed_jewellery(v_branch, 'PRECIOUS', 'Gold Stud Earrings 22K', 'Gold Earrings', 'GJ9000003', 1750000, 'GOLD', '22K', 2.1, 2.05, '7113', '8901230000490');
  perform pg_temp.seed_jewellery(v_branch, 'PRECIOUS', 'Gold Stud Earrings 22K', 'Gold Earrings', 'GJ9000004', 1750000, 'GOLD', '22K', 2.1, 2.05, '7113', '8901230000506');
  perform pg_temp.seed_jewellery(v_branch, 'PRECIOUS', 'Gold Bangle 22K', 'Gold Bangles', 'GJ9000005', 9800000, 'GOLD', '22K', 12.4, 12.3, '7113', '8901230000513');
  perform pg_temp.seed_jewellery(v_branch, 'PRECIOUS', 'Gold Pendant 22K', 'Gold Pendants', 'GJ9000006', 2350000, 'GOLD', '22K', 2.9, 2.85, '7113', '8901230000520');
  perform pg_temp.seed_jewellery(v_branch, 'PRECIOUS', 'Silver Anklet 925', 'Silver', 'GJ9000007', 620000, 'SILVER', '925', 45, 44.5, '7113', '8901230000537');
  perform pg_temp.seed_jewellery(v_branch, 'PRECIOUS', 'Silver Pooja Plate 925', 'Silver', 'GJ9000008', 1450000, 'SILVER', '925', 120, 118, '7113', '8901230000544');
end
$seed$;

reset role;
commit;

-- summary (read-only)
select
  (select count(*) from retailos.products)                                              as clothing_styles,
  (select count(*) from retailos.product_variants)                                      as clothing_variants,
  (select coalesce(sum(on_hand), 0) from retailos.inventory_balances)                   as clothing_pieces_in_stock,
  (select count(*) from retailos.jewellery_items where status = 'IN_STOCK')             as jewellery_pieces_in_stock,
  (select count(*) from retailos.barcode_aliases)                                       as barcodes,
  (select count(*) from retailos.categories)                                            as categories;
